import test from 'node:test';import assert from 'node:assert/strict';
import {createSaveFeedback,mountSaveFeedback} from '../save-feedback.js';
function clock(){let value=0;return {now:()=>value,advance:n=>value+=n};}
test('only a successful write earns a saved timestamp, which ages without claiming another save',()=>{const c=clock(),f=createSaveFeedback({now:c.now,formatTime:n=>'time:'+n});assert.equal(f.state.text,'Unsaved changes');assert.equal(f.state.savedAt,null);f.saved();assert.equal(f.state.text,'Saved just now');assert.equal(f.state.savedAt,0);c.advance(61000);assert.equal(f.state.text,'Saved 1 min ago');assert.equal(f.state.savedAt,0);f.changed();assert.equal(f.state.text,'Unsaved changes');assert.equal(f.state.timestamp,'time:0');f.saved();assert.equal(f.state.savedAt,61000);assert.equal(f.state.text,'Saved just now');});
test('saving a checkpoint during an interaction does not claim its unresolved outcome was saved',()=>{const c=clock(),f=createSaveFeedback({now:c.now});f.saved({checkpointOnly:true});assert.equal(f.state.kind,'dirty');assert.equal(f.state.text,'Unsaved changes');assert.match(f.state.detail,/before this interaction/);assert.match(f.state.detail,/Finish the interaction/);c.advance(50);f.saved();assert.equal(f.state.dirty,false);assert.equal(f.state.checkpointOnly,false);assert.equal(f.state.savedAt,50);});
test('a failed write remains unavailable through changes and clears only after storage succeeds',()=>{const c=clock(),f=createSaveFeedback({now:c.now});f.saved();c.advance(1000);f.failed();assert.equal(f.state.text,'Save unavailable — export a backup');assert.equal(f.state.savedAt,0);f.changed();assert.equal(f.state.unavailable,true);assert.equal(f.state.savedAt,0);f.saved();assert.equal(f.state.unavailable,false);assert.equal(f.state.savedAt,1000);assert.equal(f.state.text,'Saved just now');});
test('a failed traveller-slot write is reported without denying that the main save succeeded',()=>{const f=createSaveFeedback();f.saved({profileSaved:false});assert.equal(f.state.kind,'saved');assert.equal(f.state.unavailable,false);assert.match(f.state.detail,/traveller slot could not be updated/);assert.match(f.state.detail,/Export a backup/);f.saved({profileSaved:true});assert.doesNotMatch(f.state.detail,/could not/);});
test('loading an older save never invents a just-now storage timestamp',()=>{const f=createSaveFeedback({now:()=>3600000});f.loaded();assert.equal(f.state.text,'Saved on this device');assert.equal(f.state.savedAt,null);f.loaded({savedAt:0});assert.equal(f.state.text,'Saved 1 hr ago');assert.equal(f.state.savedAt,0);});
function element(){const attrs={};return{attrs,textContent:'',title:'',dataset:{},classList:{add(){}},setAttribute(k,v){attrs[k]=v;}};}
test('quiet status updates age independently, expose detail accessibly, and clean up their timer',()=>{const c=clock(),el=element();let tick,cancelled=null;const f=mountSaveFeedback({element:el,now:c.now,formatTime:()=> '12:00',setInterval(fn){tick=fn;return 42;},clearInterval:id=>cancelled=id});assert.equal(el.attrs.role,'status');assert.equal(el.attrs['aria-live'],'polite');assert.equal(el.textContent,'Unsaved changes');f.saved();assert.equal(el.textContent,'Saved just now · 12:00');assert.equal(el.dataset.saveState,'saved');c.advance(61000);tick();assert.equal(el.textContent,'Saved 1 min ago · 12:00');f.failed();assert.match(el.textContent,/Save unavailable/);assert.match(el.attrs['aria-label'],/has not been stored/);f.destroy();assert.equal(cancelled,42);const before=el.textContent;c.advance(1000);tick();assert.equal(el.textContent,before);f.destroy();});
test('status feedback does not need a timer or a storage implementation',()=>{const el=element();const f=mountSaveFeedback({element:el,intervalMs:0});f.saved();assert.match(el.textContent,/Saved just now/);f.destroy();assert.throws(()=>mountSaveFeedback(),/save-status/);});

test('repeated dirty marks during movement do not rewrite the status or reformat timestamps',()=>{let formats=0,writes=0;const el=element(),set=el.setAttribute.bind(el);el.setAttribute=(k,v)=>{writes++;set(k,v);};const f=mountSaveFeedback({element:el,formatTime:()=>{formats++;return '12:00';},intervalMs:0});f.saved();f.changed();const before=writes;for(let n=0;n<1000;n++)f.changed();assert.equal(writes,before);assert.equal(formats,1);assert.equal(f.state.dirty,true);});
